// TypeScript's lever: keep the call site monomorphic so the engine can inline it.
// A union type at one property access is a megamorphic site -> no inlining.
interface Cat { kind: 'cat'; meow(): void }
interface Dog { kind: 'dog'; bark(): void }
type Pet = Cat | Dog;

function speak(p: Pet): void {
    // split on the discriminant so each branch sees ONE shape (monomorphic)
    if (p.kind === 'cat') p.meow();      // site sees only Cat
    else p.bark();                        // site sees only Dog
}

// measure shape/megamorphism in the JS profile; TypeScript adds no inlining
// of its own - the compiled output is the same JS either way.
